1	import React, { useCallback, useEffect, useRef, useState } from 'react';
2	import { motion, AnimatePresence } from 'framer-motion';
3	import {
4	    submitOracleCommandStream,
5	    submitOracleCommand,
6	    subscribeOracleCommandState,
7	    type OracleCommandState
8	} from '../../lib/oracleCommandBridge';
9	import { apiFetch } from '../../lib/runtime';
10	import VisualSynthesisLane from './VisualSynthesisLane';
11	import OracleToolOrbs from './OracleToolOrbs';
12	import OracleTerminal from './OracleTerminal';
13	
14	interface ChatMessage {
15	    id: string;
16	    role: 'user' | 'nexus';
17	    content: string;
18	    streaming?: boolean;
19	    timestamp: string;
20	    files?: UploadedFile[];
21	}
22	
23	interface UploadedFile {
24	    name: string;
25	    type: string;
26	    dataUrl: string;
27	    size: number;
28	}
29	
30	interface ImageModel {
31	    id: string;
32	    label: string;
33	    provider: string;
34	}
35	
36	type TabId = 'context' | 'research' | 'code' | 'visual' | 'ops';
37	
38	const TABS: { id: TabId; label: string; icon: string }[] = [
39	    { id: 'context', label: 'Context',  icon: '◈' },
40	    { id: 'research', label: 'Research', icon: '◎' },
41	    { id: 'code',    label: 'Code',     icon: '⬡' },
42	    { id: 'visual',  label: 'Visual',   icon: '◆' },
43	    { id: 'ops',     label: 'Ops',      icon: '◉' }
44	];
45	
46	const REASONING_LEVELS = ['low', 'medium', 'high', 'council'] as const;
47	type ReasoningLevel = typeof REASONING_LEVELS[number];
48	
49	const REASONING_COLORS: Record<ReasoningLevel, string> = {
50	    low:     'var(--text-dim)',
51	    medium:  'var(--cyan-glow)',
52	    high:    'var(--gold-solar)',
53	    council: 'var(--red-fusion)'
54	};
55	
56	export default function OraclePage() {
57	    const [messages, setMessages] = useState<ChatMessage[]>([{
58	        id: 'boot',
59	        role: 'nexus',
60	        content: 'NEXUS — Oracle online. All systems nominal. What directive shall I process?',
61	        timestamp: new Date().toISOString()
62	    }]);
63	    const [input, setInput]           = useState('');
64	    const [activeTab, setActiveTab]   = useState<TabId>('context');
65	    const [reasoning, setReasoning]   = useState<ReasoningLevel>('medium');
66	    const [terminalOpen, setTerminalOpen] = useState(false);
67	    const [dragOver, setDragOver]     = useState(false);
68	    const [pendingFiles, setPendingFiles] = useState<UploadedFile[]>([]);
69	    const [isListening, setIsListening] = useState(false);
70	    const [imageModels, setImageModels] = useState<{ kie: ImageModel[]; remote: ImageModel[] }>({ kie: [], remote: [] });
71	    const [oracleState, setOracleState] = useState<OracleCommandState | null>(null);
72	    const [models, setModels]          = useState<any[]>([]);
73	    const [selectedModel, setSelectedModel] = useState<string>('qwen-liberated:latest');
74	
75	    const chatEndRef   = useRef<HTMLDivElement>(null);
76	    const fileInputRef = useRef<HTMLInputElement>(null);
77	    const recognitionRef = useRef<any>(null);
78	
79	    // Subscribe to oracle state
80	    useEffect(() => {
81	        return subscribeOracleCommandState(setOracleState);
82	    }, []);
83	
84	    // Auto-scroll chat
85	    useEffect(() => {
86	        chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
87	    }, [messages]);
88	
89	    // Load models + image model catalog
90	    useEffect(() => {
91	        apiFetch('/api/neural/models').then(r => r.json()).then(setModels).catch(() => {});
92	        apiFetch('/api/neural/images/models').then(r => r.json()).then(setImageModels).catch(() => {});
93	    }, []);
94	
95	    const addMessage = useCallback((msg: ChatMessage) => {
96	        setMessages(prev => [...prev, msg]);
97	    }, []);
98	
99	    const updateLastNexus = useCallback((patch: Partial<ChatMessage>) => {
100	        setMessages(prev => {
101	            const idx = [...prev].reverse().findIndex(m => m.role === 'nexus');
102	            if (idx === -1) return prev;
103	            const realIdx = prev.length - 1 - idx;
104	            return prev.map((m, i) => i === realIdx ? { ...m, ...patch } : m);
105	        });
106	    }, []);
107	
108	    const handleSubmit = useCallback(async () => {
109	        const cmd = input.trim();
110	        if (!cmd && pendingFiles.length === 0) return;
111	        setInput('');
112	
113	        const userMsg: ChatMessage = {
114	            id: `u-${Date.now()}`,
115	            role: 'user',
116	            content: cmd || '[file upload]',
117	            timestamp: new Date().toISOString(),
118	            files: pendingFiles.length > 0 ? [...pendingFiles] : undefined
119	        };
120	        addMessage(userMsg);
121	        setPendingFiles([]);
122	
123	        const nexusId = `n-${Date.now()}`;
124	        addMessage({ id: nexusId, role: 'nexus', content: '', streaming: true, timestamp: new Date().toISOString() });
125	
126	        const useCouncil = reasoning === 'council';
127	
128	        if (!useCouncil) {
129	            // Streaming path — near-realtime
130	            try {
131	                await submitOracleCommandStream({
132	                    command: cmd || 'describe uploaded files',
133	                    source: 'typed',
134	                    modelId: selectedModel,
135	                    onChunk: (chunk) => {
136	                        if (chunk.type === 'token') {
137	                            setMessages(prev => prev.map(m =>
138	                                m.id === nexusId
139	                                    ? { ...m, content: m.content + (chunk.token || ''), streaming: true }
140	                                    : m
141	                            ));
142	                        } else if (chunk.type === 'done') {
143	                            setMessages(prev => prev.map(m =>
144	                                m.id === nexusId
145	                                    ? { ...m, content: chunk.content || m.content, streaming: false }
146	                                    : m
147	                            ));
148	                        } else if (chunk.type === 'error') {
149	                            setMessages(prev => prev.map(m =>
150	                                m.id === nexusId
151	                                    ? { ...m, content: `[Oracle error: ${chunk.error}]`, streaming: false }
152	                                    : m
153	                            ));
154	                        }
155	                    }
156	                });
157	            } catch (err: any) {
158	                updateLastNexus({ content: `[Stream failed: ${err.message}]`, streaming: false });
159	            }
160	        } else {
161	            // Council mode — blocking with phase display
162	            try {
163	                const result = await submitOracleCommand({
164	                    command: cmd,
165	                    source: 'typed',
166	                    useCouncil: true
167	                });
168	                const content = result?.response || result?.content || JSON.stringify(result);
169	                updateLastNexus({ content: String(content), streaming: false });
170	            } catch (err: any) {
171	                updateLastNexus({ content: `[Council error: ${err.message}]`, streaming: false });
172	            }
173	        }
174	    }, [input, pendingFiles, reasoning, selectedModel, addMessage, updateLastNexus]);
175	
176	    const handleKeyDown = useCallback((e: React.KeyboardEvent) => {
177	        if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSubmit(); }
178	    }, [handleSubmit]);
179	
180	    const handleFileDrop = useCallback((files: FileList | null) => {
181	        if (!files) return;
182	        const allowed = ['application/pdf', 'image/png', 'image/jpeg', 'image/gif', 'image/webp',
183	            'text/markdown', 'text/plain', 'application/x-python', 'text/x-python'];
184	        Array.from(files).forEach(file => {
185	            if (!allowed.some(t => file.type === t || file.name.endsWith('.md') || file.name.endsWith('.py') || file.name.endsWith('.ts'))) return;
186	            const reader = new FileReader();
187	            reader.onload = () => {
188	                setPendingFiles(prev => [...prev, {
189	                    name: file.name,
190	                    type: file.type,
191	                    dataUrl: reader.result as string,
192	                    size: file.size
193	                }]);
194	            };
195	            reader.readAsDataURL(file);
196	        });
197	    }, []);
198	
199	    const toggleVoice = useCallback(() => {
200	        const SR = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
201	        if (!SR) return;
202	        if (isListening) {
203	            recognitionRef.current?.stop();
204	            setIsListening(false);
205	            return;
206	        }
207	        const rec = new SR();
208	        rec.lang = 'en-US';
209	        rec.continuous = false;
210	        rec.onresult = (e: any) => {
211	            const text: string = e.results[0]?.[0]?.transcript || '';
212	            setInput(prev => (prev + ' ' + text).trim());
213	            setIsListening(false);
214	        };
215	        rec.onend = () => setIsListening(false);
216	        rec.start();
217	        recognitionRef.current = rec as any;
218	        setIsListening(true);
219	    }, [isListening]);
220	
221	    const cycleReasoning = useCallback(() => {
222	        setReasoning(prev => {
223	            const idx = REASONING_LEVELS.indexOf(prev);
224	            return REASONING_LEVELS[(idx + 1) % REASONING_LEVELS.length];
225	        });
226	    }, []);
227	
228	    const isBusy = oracleState?.phase === 'submitted' || oracleState?.phase === 'deliberating';
229	
230	    return (
231	        <div className="oracle-page" onDragOver={e => { e.preventDefault(); setDragOver(true); }}
232	            onDragLeave={() => setDragOver(false)}
233	            onDrop={e => { e.preventDefault(); setDragOver(false); handleFileDrop(e.dataTransfer.files); }}
234	        >
235	            {/* Drop overlay */}
236	            <AnimatePresence>
237	                {dragOver && (
238	                    <motion.div className="oracle-drop-overlay"
239	                        initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
240	                        <span>Drop files into NEXUS</span>
241	                    </motion.div>
242	                )}
243	            </AnimatePresence>
244	
245	            {/* Main layout */}
246	            <div className="oracle-layout">
247	
248	                {/* LEFT — Category tabs */}
249	                <div className="oracle-tabs">
250	                    {TABS.map(tab => (
251	                        <button key={tab.id} className={`oracle-tab ${activeTab === tab.id ? 'active' : ''}`}
252	                            onClick={() => setActiveTab(tab.id)}>
253	                            <span className="tab-icon">{tab.icon}</span>
254	                            <span className="tab-label">{tab.label}</span>
255	                        </button>
256	                    ))}
257	                    <div className="oracle-tab-spacer"/>
258	                    <button className="oracle-tab terminal-toggle" onClick={() => setTerminalOpen(p => !p)}>
259	                        <span className="tab-icon">_</span>
260	                        <span className="tab-label">Terminal</span>
261	                    </button>
262	                </div>
263	
264	                {/* CENTER — Chat + orbs */}
265	                <div className="oracle-center">
266	
267	                    {/* Tool orbs or tab content */}
268	                    <div className="oracle-content-area">
269	                        {activeTab === 'visual' ? (
270	                            <VisualSynthesisLane models={imageModels} />
271	                        ) : (
272	                            <OracleToolOrbs activeTab={activeTab} />
273	                        )}
274	                    </div>
275	
276	                    {/* Chat thread */}
277	                    <div className="oracle-chat">
278	                        <div className="oracle-messages">
279	                            {messages.map(msg => (
280	                                <motion.div key={msg.id} className={`oracle-msg oracle-msg--${msg.role}`}
281	                                    initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }}
282	                                    transition={{ duration: 0.2 }}>
283	                                    <span className="msg-label">
284	                                        {msg.role === 'user' ? 'NEXUS' : 'ORACLE'}
285	                                    </span>
286	                                    <div className="msg-body">
287	                                        {msg.content}
288	                                        {msg.streaming && <span className="cursor-blink">▋</span>}
289	                                    </div>
290	                                    {msg.files && msg.files.length > 0 && (
291	                                        <div className="msg-files">
292	                                            {msg.files.map((f, i) => (
293	                                                <span key={i} className="msg-file-pill">{f.name}</span>
294	                                            ))}
295	                                        </div>
296	                                    )}
297	                                </motion.div>
298	                            ))}
299	                            {isBusy && (
300	                                <div className="oracle-phase-indicator">
301	                                    <span className="phase-dot"/>
302	                                    {oracleState?.phase} · {oracleState?.elapsedMs ? Math.floor(oracleState.elapsedMs / 1000) + 's' : '...'}
303	                                </div>
304	                            )}
305	                            <div ref={chatEndRef}/>
306	                        </div>
307	
308	                        {/* Pending file pills */}
309	                        {pendingFiles.length > 0 && (
310	                            <div className="oracle-pending-files">
311	                                {pendingFiles.map((f, i) => (
312	                                    <span key={i} className="pending-file-pill">
313	                                        {f.name}
314	                                        <button onClick={() => setPendingFiles(p => p.filter((_, j) => j !== i))}>×</button>
315	                                    </span>
316	                                ))}
317	                            </div>
318	                        )}
319	
320	                        {/* Input bar */}
321	                        <div className="oracle-input-bar">
322	                            {/* Plus — file picker */}
323	                            <button className="input-action input-plus" onClick={() => fileInputRef.current?.click()} title="Attach file">
324	                                +
325	                            </button>
326	                            <input ref={fileInputRef} type="file" multiple hidden
327	                                accept=".pdf,.png,.jpg,.jpeg,.gif,.webp,.md,.py,.ts,.txt"
328	                                onChange={e => handleFileDrop(e.target.files)}/>
329	
330	                            <textarea
331	                                className="oracle-textarea"
332	                                value={input}
333	                                onChange={e => setInput(e.target.value)}
334	                                onKeyDown={handleKeyDown}
335	                                placeholder="Ask NEXUS..."
336	                                rows={1}
337	                            />
338	
339	                            {/* Model selector */}
340	                            <select className="oracle-model-select" value={selectedModel}
341	                                onChange={e => setSelectedModel(e.target.value)}>
342	                                {models.length > 0
343	                                    ? models.map((m: any) => <option key={m.id} value={m.id}>{m.name || m.id}</option>)
344	                                    : <option value="qwen-liberated:latest">Qwen Local</option>}
345	                            </select>
346	
347	                            {/* Reasoning level */}
348	                            <button className="input-action reasoning-level"
349	                                style={{ color: REASONING_COLORS[reasoning] }}
350	                                onClick={cycleReasoning}
351	                                title={`Reasoning: ${reasoning}`}>
352	                                {reasoning.slice(0, 3).toUpperCase()}
353	                            </button>
354	
355	                            {/* Mic */}
356	                            <button className={`input-action input-mic ${isListening ? 'active' : ''}`}
357	                                onClick={toggleVoice} title="Voice input">
358	                                {isListening ? '◉' : '🎤'}
359	                            </button>
360	
361	                            {/* Send */}
362	                            <button className="input-action input-send" onClick={handleSubmit} disabled={isBusy}>
363	                                {isBusy ? '⟳' : '↑'}
364	                            </button>
365	                        </div>
366	                    </div>
367	                </div>
368	            </div>
369	
370	            {/* Terminal pane (collapsible) */}
371	            <AnimatePresence>
372	                {terminalOpen && (
373	                    <motion.div className="oracle-terminal-pane"
374	                        initial={{ height: 0 }} animate={{ height: 320 }} exit={{ height: 0 }}
375	                        transition={{ duration: 0.25 }}>
376	                        <OracleTerminal />
377	                    </motion.div>
378	                )}
379	            </AnimatePresence>
380	
381	            <style>{ORACLE_STYLES}</style>
382	        </div>
383	    );
384	}
385	
386	const ORACLE_STYLES = `
