393	  font-family: 'JetBrains Mono', 'Fira Code', monospace;
394	  position: relative;
395	  overflow: hidden;
396	}
397	
398	.oracle-drop-overlay {
399	  position: absolute;
400	  inset: 0;
401	  background: rgba(159,232,115,0.08);
402	  border: 2px dashed var(--cyan-glow);
403	  z-index: 100;
404	  display: flex;
405	  align-items: center;
406	  justify-content: center;
407	  font-size: 1.4rem;
