410	}
411	
412	.oracle-layout {
413	  display: flex;
414	  flex: 1;
415	  overflow: hidden;
416	  min-height: 0;
417	}
418	
419	/* LEFT TABS */
420	.oracle-tabs {
421	  display: flex;
422	  flex-direction: column;
423	  width: 88px;
424	  border-right: 1px solid rgba(159,232,115,0.12);
425	  padding: 8px 0;
426	  gap: 2px;
427	  flex-shrink: 0;
428	}
429	
