471	}
472	
473	/* CHAT */
474	.oracle-chat {
475	  display: flex;
476	  flex-direction: column;
477	  flex: 1;
478	  overflow: hidden;
479	  min-height: 0;
480	}
481	
482	.oracle-messages {
483	  flex: 1;
484	  overflow-y: auto;
485	  padding: 12px 16px;
486	  display: flex;
487	  flex-direction: column;
488	  gap: 10px;
489	}
490	
