515	  background: rgba(159,232,115,0.06);
516	  border-color: rgba(159,232,115,0.2);
517	}
518	
519	.cursor-blink {
520	  animation: blink 0.8s step-end infinite;
521	  color: var(--cyan-glow);
522	}
523	@keyframes blink { 50% { opacity: 0; } }
524	
525	.msg-files { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 4px; }
526	.msg-file-pill {
527	  font-size: 10px;
528	  padding: 2px 8px;
529	  background: rgba(159,232,115,0.1);
530	  border: 1px solid rgba(159,232,115,0.2);
531	  border-radius: 2px;
532	  color: var(--cyan-glow);
533	}
534	
535	.oracle-phase-indicator {
536	  display: flex;
537	  align-items: center;
538	  gap: 8px;
539	  font-size: 11px;
540	  color: var(--gold-solar);
541	  opacity: 0.7;
542	  padding: 0 4px;
543	}
