551	
552	/* PENDING FILES */
553	.oracle-pending-files {
554	  display: flex;
555	  flex-wrap: wrap;
556	  gap: 6px;
557	  padding: 6px 16px;
558	  border-top: 1px solid rgba(159,232,115,0.08);
559	}
560	.pending-file-pill {
561	  display: flex;
562	  align-items: center;
563	  gap: 6px;
564	  font-size: 11px;
565	  padding: 3px 8px;
566	  background: rgba(118,185,0,0.1);
567	  border: 1px solid rgba(118,185,0,0.3);
568	  border-radius: 2px;
569	  color: var(--gold-solar);
570	}
571	.pending-file-pill button {
572	  background: none; border: none; color: var(--red-fusion);
573	  cursor: pointer; font-size: 13px; padding: 0; line-height: 1;
574	}
575	
576	/* INPUT BAR */
577	.oracle-input-bar {
578	  display: flex;
579	  align-items: flex-end;
580	  gap: 8px;
581	  padding: 10px 16px;
582	  border-top: 1px solid rgba(159,232,115,0.12);
583	  background: rgba(8,8,8,0.6);
584	}
585	
586	.oracle-textarea {
587	  flex: 1;
588	  background: rgba(255,255,255,0.03);
589	  border: 1px solid rgba(159,232,115,0.15);
590	  border-radius: 2px;
591	  color: var(--silver-albedo);
592	  font-family: inherit;
593	  font-size: 13px;
594	  padding: 8px 10px;
595	  resize: none;
596	  outline: none;
597	  min-height: 36px;
598	  max-height: 120px;
599	  line-height: 1.5;
600	  transition: border-color 0.15s;
601	}
602	.oracle-textarea:focus { border-color: rgba(159,232,115,0.4); }
603	.oracle-textarea::placeholder { color: var(--text-dim); opacity: 0.5; }
604	
605	.oracle-model-select {
606	  background: rgba(255,255,255,0.03);
607	  border: 1px solid rgba(159,232,115,0.12);
608	  color: var(--text-dim);
609	  font-family: inherit;
610	  font-size: 10px;
611	  padding: 4px 6px;
612	  outline: none;
